select * from b_tongcheng_undo_data where
id > #{minId} and
local_id = #{localId} and status =1 and push_status =1 order by id asc limit 2000;

select
    count(*) as quantity,
    local_id as localId
from
    b_tongcheng_undo_data
where
    push_status = #{pushStatus}
    and status = #{status}

        and local_id in

              #{localId}


    and update_time >= #{startTime}
group by
    local_id
